const run = (cwd, ...args) => spawnSync(args[0], args.slice(1), { cwd, encoding: "utf8" });
const git = (cwd, ...args) => run(cwd, "git", "--literal-pathspecs", ...args);
async function repository() { const root=await mkdtemp(join(tmpdir(),"why-repository-")); git(root,"init","-q"); git(root,"config","user.email","fixture@example.invalid"); git(root,"config","user.name","Fixture"); return root; }
async function put(root,path,content){await mkdir(dirname(join(root,path)),{recursive:true});await writeFile(join(root,path),content);}
function commit(root,message,...paths){assert.equal(git(root,"add","--",...paths).status,0);assert.equal(git(root,"commit","-qm",message).status,0);}
function analyze(root,options){return JSON.parse(analyzeRepository({repo:root,...options}));}
const forgedAnalyzerDirectories=new Set();
after(async()=>{for(const directory of forgedAnalyzerDirectories)await rm(directory,{recursive:true,force:true});});
async function forgedAnalyzer(executable){const temp=await mkdtemp(join(tmpdir(),"why-forged-analyzer-")),copy=join(temp,"why");await cp(new URL("../../../dot_agents/skills/why/",import.meta.url),copy,{recursive:true});const core=join(copy,"scripts/why-core.mjs"),source=await readFile(core,"utf8"),trusted='const SYSTEM_GIT = "/usr/bin/git";',instrumented=source.replace(trusted,`const SYSTEM_GIT = ${JSON.stringify(executable)};`);assert.notEqual(instrumented,source);assert.equal(instrumented.includes(trusted),false);await writeFile(core,instrumented);const {analyzeRepository:isolatedAnalyze}=await import(`${pathToFileURL(join(copy,"scripts/analyze-why.mjs")).href}?fixture=${Date.now()}-${Math.random()}`);forgedAnalyzerDirectories.add(temp);return{analyze:(root,options)=>JSON.parse(isolatedAnalyze({repo:root,...options}))};}

test("production Git invocation ignores leading PATH executables at root and nested repositories",async()=>{for(const nested of [false,true]){const root=await repository(),bin=await mkdtemp(join(tmpdir(),"why-untrusted-git-")),oldPath=process.env.PATH;try{const work=nested?join(root,"nested"):root;if(nested){await mkdir(work);git(work,"init","-q");git(work,"config","user.email","fixture@example.invalid");git(work,"config","user.name","Fixture")}await put(work,"target.md","Why: trusted Git only\n");commit(work,"base","target.md");const marker=join(root,"PATH_GIT_RAN"),wrapper=join(bin,"git");await writeFile(wrapper,`#!/bin/sh\n: > ${JSON.stringify(marker)}\nexec /usr/bin/git "$@"\n`);await chmod(wrapper,0o755);process.env.PATH=`${bin}:${oldPath}`;assert.equal(analyze(work,{kind:"path",target:"target.md"}).classification,"documented");assert.equal(await readFile(marker).catch(()=>null),null)}finally{process.env.PATH=oldPath;await rm(bin,{recursive:true,force:true});await rm(root,{recursive:true,force:true});}}});

test("production preload cannot restore the removed Git override",async()=>{const root=await repository(),bin=await mkdtemp(join(tmpdir(),"why-preload-"));try{await put(root,"target.md","Why: trusted Git only\n");commit(root,"base","target.md");const marker=join(root,"OVERRIDE_RAN"),wrapper=join(bin,"git"),preload=join(bin,"preload.mjs"),core=new URL("../../../dot_agents/skills/why/scripts/why-core.mjs",import.meta.url).href,entry=new URL("../../../dot_agents/skills/why/scripts/analyze-why.mjs",import.meta.url);await writeFile(wrapper,`#!/bin/sh\n: > ${JSON.stringify(marker)}\nexec /usr/bin/git "$@"\n`);await chmod(wrapper,0o755);await writeFile(preload,`const core=await import(${JSON.stringify(core)});if(typeof core.setTestGitExecutable==='function')core.setTestGitExecutable(${JSON.stringify(wrapper)});\n`);const result=spawnSync(process.execPath,[entry.pathname,"--repo",root,"--kind","path","--target","target.md"],{encoding:"utf8",env:{...process.env,NODE_TEST_CONTEXT:"forged",NODE_OPTIONS:`--import=${preload}`}});assert.equal(result.status,0,result.stderr);assert.match(result.stdout,/\| trusted Git only \| documented \|/);assert.equal(await readFile(marker).catch(()=>null),null)}finally{await rm(bin,{recursive:true,force:true});await rm(root,{recursive:true,force:true});}});

test("Git child receives only fixed safe environment",async()=>{const root=await repository(),bin=await mkdtemp(join(tmpdir(),"why-child-env-")),real="/usr/bin/git",saved={...process.env};try{await put(root,"target.md","Why: safe child environment\n");commit(root,"base","target.md");const capture=join(bin,"environment.json"),wrapper=join(bin,"git");await writeFile(wrapper,`#!${process.execPath}\nconst fs=require('fs'),cp=require('child_process');fs.writeFileSync(${JSON.stringify(capture)},JSON.stringify(process.env));const r=cp.spawnSync(${JSON.stringify(real)},process.argv.slice(2),{stdio:'inherit',env:process.env});process.exit(r.status??1);\n`);await chmod(wrapper,0o755);for(const key of ["GIT_DIR","LD_PRELOAD","DYLD_INSERT_LIBRARIES","BASH_ENV","ENV","NODE_OPTIONS"])process.env[key]="/untrusted/injection";const isolated=await forgedAnalyzer(wrapper);assert.equal(isolated.analyze(root,{kind:"path",target:"target.md"}).classification,"documented");const child=JSON.parse(await readFile(capture,"utf8"));assert.equal(child.PATH,"/usr/bin:/bin");for(const key of ["GIT_DIR","LD_PRELOAD","DYLD_INSERT_LIBRARIES","BASH_ENV","ENV","NODE_OPTIONS"])assert.equal(child[key],undefined,key)}finally{for(const key of Object.keys(process.env))delete process.env[key];Object.assign(process.env,saved);await rm(bin,{recursive:true,force:true});await rm(root,{recursive:true,force:true});}});

