test("P2-2aa closes bounded Markdown transforms without tainting literal delimiters",async()=>{const hostile=["[API_](https://safe.invalid/(a))KEY=nested-secret","API_` KEY `=one-code-secret","API_`` KEY ``=two-code-secret","ghp_abcdefghijklmnopqrstuvwxyz1234567890,SERVICE_TOKEN&#61;mixed-secret"];for(const [index,value] of hostile.entries()){const root=await repository();try{const path=`hostile-${index}.md`;await put(root,path,`Why: ${value}\nConstraint: ${value}\nShape ${value}\n`);commit(root,`Reason: ${value}`,path);const manifest=analyze(root,{kind:"path",target:path}),json=JSON.stringify(manifest),report=renderWhyReport(manifest);assert.equal(manifest.disclosure.tainted,true,value);assert.doesNotMatch(json,/(?:nested|one-code|two-code|mixed)-secret/,value);assert.doesNotMatch(report,/(?:nested|one-code|two-code|mixed)-secret/,value)}finally{await rm(root,{recursive:true,force:true});}}for(const value of ["API__KEY_=clean","API_**_KEY_**=clean","API_*__KEY__*=clean"]){const root=await repository();try{await put(root,"clean.md",`## Context\n${value} because clients require it\n`);commit(root,`Reason: ${value}`,"clean.md");const manifest=analyze(root,{kind:"path",target:"clean.md"});assert.equal(manifest.disclosure.tainted,false,value);assert.match(JSON.stringify(manifest),new RegExp(value.replace(/[.*+?^${}()|[\]\\]/g,"\\$&")),value)}finally{await rm(root,{recursive:true,force:true});}}});

