test("P2-2aa authenticates deletion recreation and exact conflict stages",async()=>{const recreated=await repository();try{await put(recreated,"target.md","Why: canonical recreation\n");await put(recreated,"state.txt","old\n");commit(recreated,"base","target.md","state.txt");assert.equal(git(recreated,"rm","-q","state.txt").status,0);await put(recreated,"state.txt","new\n");const manifest=analyze(recreated,{kind:"path",target:"target.md"});assert.equal(manifest.classification,"documented");assert.doesNotMatch(manifest.unresolved.join(" "),/could not be verified/)}finally{await rm(recreated,{recursive:true,force:true});}const stageMatrix={DD:[1],AU:[2],UD:[1,2],UA:[3],DU:[1,3],AA:[2,3],UU:[1,2,3]};for(const [code,stages] of Object.entries(stageMatrix)){for(const valid of [true,false]){const root=await repository(),bin=await mkdtemp(join(tmpdir(),"why-stage-matrix-")),real=run(root,"sh","-c","command -v git").stdout.trim(),oldPath=process.env.PATH;try{await put(root,"target.md","Why: conflict rationale\n");await put(root,"x.txt","base\n");commit(root,"base","target.md","x.txt");const oid=git(root,"rev-parse","HEAD:x.txt").stdout.trim(),chosen=valid?stages:(stages.length===1?[stages[0]===1?2:1]:[stages[0]]);assert.equal(spawnSync(real,["update-index","--force-remove","--","x.txt"],{cwd:root}).status,0);assert.equal(spawnSync(real,["update-index","--index-info"],{cwd:root,input:chosen.map(stage=>`100644 ${oid} ${stage}\tx.txt`).join("\n")+"\n",encoding:"utf8"}).status,0);const wrapper=join(bin,"git");await writeFile(wrapper,`#!${process.execPath}\nconst cp=require('child_process'),a=process.argv.slice(2),r=cp.spawnSync(${JSON.stringify(real)},a,{encoding:null});if(a.includes('status'))process.stdout.write(Buffer.from(${JSON.stringify(`${code} x.txt\0`)}));else process.stdout.write(r.stdout);process.stderr.write(r.stderr);process.exit(r.status??1);\n`);await chmod(wrapper,0o755);const isolated=await forgedAnalyzer(wrapper);assert.equal(isolated.analyze(root,{kind:"path",target:"target.md"}).classification,valid?"documented":"not documented",`${code} ${chosen}`)}finally{await rm(bin,{recursive:true,force:true});await rm(root,{recursive:true,force:true});}}}});

