test("P2-2ag overflow privacy schema recount and bounds matrix",async()=>{for(const [name,path] of [["direct","API_KEY=overflow-secret.md"],["entity","API&#95;KEY=overflow-secret.md"],["control","API_\u001b[31mKEY=overflow-secret.md"],["reference","[API_]KEY=overflow-secret.md"]]){const root=await repository();try{await put(root,path,"Why: safe\n"+"x".repeat(128*1024));const encoded=analyzeRepository({repo:root,kind:"path",target:path}),manifest=JSON.parse(encoded),report=renderWhyReport(manifest),without=JSON.stringify({...manifest,disclosure:undefined}),recount={};for(const match of without.matchAll(/\[REDACTED:([^\]]+)\]/g))recount[match[1]]=(recount[match[1]]??0)+1;assert.equal(manifest.target.path,"target",name);assert.equal(manifest.target.value,"target",name);assert.deepEqual(manifest.disclosure.redactions,recount,name);assert.doesNotMatch(encoded,/overflow-secret|b64url/,name);assert.ok(Buffer.byteLength(encoded)<=16*1024);assert.ok(Buffer.byteLength(report)<=16*1024)}finally{await rm(root,{recursive:true,force:true});}}const root=await repository();try{await put(root,"target.js","export const selected = 1;\n"+"x".repeat(128*1024));const manifest=analyze(root,{kind:"symbol",target:"selected",path:"target.js:L1"});assert.equal(typeof manifest.target.path,"string");assert.equal(manifest.target.path,"target.js:L1");assert.equal(manifest.target.anchor,"target.js:L1")}finally{await rm(root,{recursive:true,force:true});}});

