test("P2-2ag rejects forged recursive blank status columns",async()=>{const rows=[["MM hides staged",async r=>{await put(r,"state.txt","stage\n");git(r,"add","state.txt");await put(r,"state.txt","work\n")}," M state.txt\0"],["MM hides worktree",async r=>{await put(r,"state.txt","stage\n");git(r,"add","state.txt");await put(r,"state.txt","work\n")},"M  state.txt\0"],["AM hides worktree",async r=>{await put(r,"new.txt","stage\n");git(r,"add","new.txt");await put(r,"new.txt","work\n")},"A  new.txt\0"],["D recreation hides untracked",async r=>{git(r,"rm","-q","state.txt");await put(r,"state.txt","recreated\n")},"D  state.txt\0"]];for(const [name,mutate,payload] of rows){const root=await repository(),sub=await repository(),bin=await mkdtemp(join(tmpdir(),"why-recursive-blank-")),real=run(root,"sh","-c","command -v git").stdout.trim(),oldPath=process.env.PATH;try{await put(root,"target.md","Why: safe\n");await put(sub,"state.txt","base\n");commit(sub,"base","state.txt");assert.equal(git(root,"-c","protocol.file.allow=always","submodule","add","-q",sub,"vendor/sub").status,0);commit(root,"base","target.md",".gitmodules","vendor/sub");const nested=join(root,"vendor/sub");await mutate(nested);const wrapper=join(bin,"git");await writeFile(wrapper,`#!/bin/sh\nif [ "$PWD" = ${JSON.stringify(nested)} ]; then case " $* " in *" status "*) printf ${JSON.stringify(payload)}; exit 0;; esac; fi\nexec ${JSON.stringify(real)} "$@"\n`);await chmod(wrapper,0o755);const isolated=await forgedAnalyzer(wrapper);const result=isolated.analyze(root,{kind:"path",target:"target.md"});assert.equal(result.classification,"not documented",name);assert.match(result.unresolved.join(" "),/could not be verified/,name)}finally{await rm(bin,{recursive:true,force:true});await rm(root,{recursive:true,force:true});await rm(sub,{recursive:true,force:true});}}});

test("P2-2ag gitlink clean forged dirty unchanged changed clean and staged matrix root and recursive",async()=>{for(const recursive of [false,true])for(const state of ["clean-forged","dirty-unchanged","changed-clean","changed-staged"]){const root=await repository(),middle=recursive?await repository():root,leaf=await repository(),bin=await mkdtemp(join(tmpdir(),"why-gitlink-matrix-")),real=run(root,"sh","-c","command -v git").stdout.trim(),oldPath=process.env.PATH;let isolated;try{await put(root,"target.md","Why: safe\n");await put(leaf,"leaf.txt","base\n");commit(leaf,"base","leaf.txt");const owner=recursive?middle:root,prefix=recursive?"deps/leaf":"vendor/leaf";assert.equal(git(owner,"-c","protocol.file.allow=always","submodule","add","-q",leaf,prefix).status,0);if(recursive){await put(middle,"middle.txt","base\n");commit(middle,"middle",".gitmodules",prefix,"middle.txt");assert.equal(git(root,"-c","protocol.file.allow=always","submodule","add","-q",middle,"vendor/middle").status,0);assert.equal(git(root,"-c","protocol.file.allow=always","submodule","update","--init","--recursive").status,0);commit(root,"root","target.md",".gitmodules","vendor/middle")}else commit(root,"root","target.md",".gitmodules",prefix);const checkout=recursive?join(root,"vendor/middle",prefix):join(root,prefix);if(state==="dirty-unchanged")await put(recursive?join(root,"vendor/middle"):checkout,recursive?"middle.txt":"leaf.txt","dirty\n");if(state.startsWith("changed-")){await put(checkout,"leaf.txt","changed\n");commit(checkout,"changed","leaf.txt");if(state==="changed-staged")git(recursive?join(root,"vendor/middle"):root,"add",prefix)}if(recursive&&state==="changed-staged")git(root,"add","vendor/middle");if(state==="clean-forged"){const wrapper=join(bin,"git"),path=recursive?"vendor/middle":"vendor/leaf";await writeFile(wrapper,`#!/bin/sh\nif [ "$PWD" = ${JSON.stringify(root)} ]; then case " $* " in *" status "*) printf ' M ${path}\\0'; exit 0;; esac; fi\nexec ${JSON.stringify(real)} "$@"\n`);await chmod(wrapper,0o755);isolated=await forgedAnalyzer(wrapper)}const result=(isolated?.analyze??analyze)(root,{kind:"path",target:"target.md"});assert.equal(result.classification,state==="clean-forged"?"not documented":"documented",`${recursive?"recursive":"root"} ${state}: ${result.unresolved.join(" | ")}`)}finally{await rm(bin,{recursive:true,force:true});await rm(root,{recursive:true,force:true});if(recursive)await rm(middle,{recursive:true,force:true});await rm(leaf,{recursive:true,force:true});}}});

