for(const scenario of [
  {name:"global clean marker",scope:"global",key:"filter.evil.clean",attributes:"global"},
  {name:"system clean marker",scope:"system",key:"filter.evil.clean",attributes:"global"},
  {name:"GIT_CONFIG_COUNT clean marker",scope:"environment",key:"filter.evil.clean",attributes:"global"},
  {name:"local include clean marker",scope:"include",key:"filter.evil.clean",attributes:"worktree",failClosed:true},
  {name:"info attributes clean marker",scope:"global",key:"filter.evil.clean",attributes:"info",failClosed:true},
  {name:"global attributes clean marker",scope:"global",key:"filter.evil.clean",attributes:"global"},
  {name:"local clean marker",scope:"local",key:"filter.evil.clean",attributes:"worktree",failClosed:true},
  {name:"local process marker",scope:"local",key:"filter.evil.process",attributes:"worktree",failClosed:true},
  {name:"local textconv marker",scope:"local",key:"diff.evil.textconv",attributes:"worktree",failClosed:true},
])test(`P2-2ak blocks ${scenario.name}`,async()=>{const root=await repository();const saved=Object.fromEntries(Object.entries(process.env).filter(([key])=>key.startsWith("GIT_CONFIG_")));try{await put(root,"target.md","Why: safe\n");await put(root,"filtered.txt","REPO\n");commit(root,"base","target.md","filtered.txt");const marker=join(root,"COMMAND_RAN"),attrs=join(root,"attrs"),config=join(root,"hostile-config"),command=`sh -c 'touch ${marker}; cat'`;await writeFile(attrs,`filtered.txt ${scenario.key.includes("diff.")?"diff":"filter"}=evil\n`);if(scenario.attributes==="worktree")await put(root,".gitattributes",await readFile(attrs));else if(scenario.attributes==="info")await put(root,".git/info/attributes",await readFile(attrs));const configure=file=>{assert.equal(git(root,"config","--file",file,"core.attributesFile",attrs).status,0);assert.equal(git(root,"config","--file",file,scenario.key,command).status,0)};if(scenario.scope==="local")assert.equal(git(root,"config",scenario.key,command).status,0);else if(scenario.scope==="include"){const included=join(root,"included-config");assert.equal(git(root,"config","--file",included,scenario.key,command).status,0);assert.equal(git(root,"config","include.path",included).status,0)}else if(scenario.scope==="environment"){process.env.GIT_CONFIG_COUNT="2";process.env.GIT_CONFIG_KEY_0="core.attributesFile";process.env.GIT_CONFIG_VALUE_0=attrs;process.env.GIT_CONFIG_KEY_1=scenario.key;process.env.GIT_CONFIG_VALUE_1=command}else{configure(config);process.env[scenario.scope==="global"?"GIT_CONFIG_GLOBAL":"GIT_CONFIG_SYSTEM"]=config;if(scenario.scope==="system")process.env.GIT_CONFIG_GLOBAL=join(root,"empty-global")}await put(root,"filtered.txt","REPO\n");const result=analyze(root,{kind:"path",target:"target.md"});assert.equal(result.classification,scenario.failClosed?"not documented":"documented");assert.equal(await readFile(marker).catch(()=>null),null)}finally{for(const key of Object.keys(process.env))if(key.startsWith("GIT_CONFIG_"))delete process.env[key];Object.assign(process.env,saved);await rm(root,{recursive:true,force:true});}});

