test("P2-2am ignores inherited Git repository routing without mixing identities or executing hooks",async()=>{const root=await repository(),foreign=await repository();const saved=Object.fromEntries(Object.entries(process.env).filter(([key])=>key.startsWith("GIT_")));try{await put(root,"target.md","base\n");commit(root,"base","target.md");await put(root,"target.md","local-state\n");await put(foreign,"target.md","base\n");commit(foreign,"base","target.md");await put(foreign,"target.md","local-state\n");commit(foreign,"Why: FOREIGN HISTORY","target.md");const marker=join(root,"MARKER_RAN"),monitor=join(foreign,"monitor");await writeFile(monitor,`#!/bin/sh\n: > ${JSON.stringify(marker)}\nprintf 'token\\n'\n`);await chmod(monitor,0o755);git(foreign,"config","core.fsmonitor",monitor);const expected=analyze(root,{kind:"path",target:"target.md"});assert.equal(expected.classification,"not documented");const routes={GIT_DIR:join(foreign,".git"),GIT_WORK_TREE:foreign,GIT_INDEX_FILE:join(foreign,".git/index"),GIT_COMMON_DIR:join(foreign,".git"),GIT_OBJECT_DIRECTORY:join(foreign,".git/objects"),GIT_ALTERNATE_OBJECT_DIRECTORIES:join(foreign,".git/objects"),GIT_NAMESPACE:"foreign",GIT_SHALLOW_FILE:join(foreign,".git/shallow"),GIT_REPLACE_REF_BASE:"refs/foreign/replace",GIT_CEILING_DIRECTORIES:root,GIT_DISCOVERY_ACROSS_FILESYSTEM:"1",GIT_NO_REPLACE_OBJECTS:"1"};for(const [key,value] of Object.entries(routes)){process.env[key]=value;const actual=analyze(root,{kind:"path",target:"target.md"});assert.deepEqual(actual,expected,key);delete process.env[key]}assert.equal(await readFile(marker).catch(()=>null),null)}finally{for(const key of Object.keys(process.env))if(key.startsWith("GIT_"))delete process.env[key];Object.assign(process.env,saved);await rm(root,{recursive:true,force:true});await rm(foreign,{recursive:true,force:true});}});

